<?php require 'includes/bootstrap.php';if(empty($_SESSION['pending_uid']))go('login.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('SELECT * FROM users WHERE id=?');$s->execute([$_SESSION['pending_uid']]);$u=$s->fetch();$hash=hash_hmac('sha256',trim($_POST['otp']??''),$config['app_secret']);if($u&&$u['otp_hash']&&$u['otp_expires']>date('Y-m-d H:i:s')&&hash_equals($u['otp_hash'],$hash)){session_regenerate_id(true);$_SESSION['uid']=$u['id'];unset($_SESSION['pending_uid']);$pdo->prepare('UPDATE users SET otp_hash=NULL,otp_expires=NULL WHERE id=?')->execute([$u['id']]);audit('login_success',(int)$u['id']);go('dashboard.php');}$error='Invalid or expired code.';}$pageTitle='One-time code';require 'includes/header.php';?><section class="card narrow"><h1>Email verification code</h1><?php if($error):?><p class="error"><?=e($error)?></p><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>6-digit code<input name="otp" inputmode="numeric" pattern="[0-9]{6}" required></label><button class="button">Verify and sign in</button></form></section><?php require 'includes/footer.php';?>
